import base64
from pathlib import Path
p = Path("webcms/admin/admin_api.py")
txt = p.read_text()
old = base64.b64decode("").decode()
new = base64.b64decode("").decode()
if old not in txt: print("old block not found")
else:
    txt = txt.replace(old, new)
    p.write_text(txt)
    print("fixed author display")